/* eslint-disable no-undef */
/**
 * Service worker for the Collective Energy Africa monitor.
 *
 * Hand-written rather than generated by next-pwa/Workbox. Workbox is ~20 KB of
 * runtime plus a build plugin, and what this app actually needs is three
 * routing rules. The rules below are the whole of it, and each one is a
 * deliberate answer to "what happens when this is stale?".
 *
 * WHAT THIS DOES AND DOES NOT BUY. Next already serves /_next/static with
 * `immutable` and a one-year max-age, so a returning visitor was already
 * getting the 3D scene chunk from disk cache without a network round trip.
 * This worker does not make that faster. What it adds is:
 *
 *   - the app opens and renders with no network at all;
 *   - the cache survives the browser evicting its HTTP disk cache, which it
 *     does silently and often on a phone under storage pressure;
 *   - installability. Chrome will not offer to install a site without a
 *     service worker that has a fetch handler.
 *
 * Saying that plainly matters because "add a service worker to make it fast"
 * is a common way to add a whole caching layer and measure no improvement.
 */

// Bump to invalidate everything. The version is in the cache NAME, so
// activating a new worker orphans the old caches and the cleanup below
// removes them — there is no partial-upgrade state to reason about.
const VERSION = "v1";
const STATIC_CACHE = `cea-static-${VERSION}`;
const PAGES_CACHE = `cea-pages-${VERSION}`;

/**
 * Deliberately NOT precaching the app shell or the 3D chunk on install.
 *
 * Two reasons. Next's asset filenames carry content hashes that change every
 * build, so a hardcoded precache list is wrong the moment anyone deploys, and
 * keeping it right means a build step this project does not have. And a
 * precache of the ~226 KB scene chunk would fire on every install regardless
 * of device — quietly overriding lib/scene-load-policy.ts, which exists to
 * NOT spend a phone's data plan on a 3D view it will not display anyway.
 *
 * Everything below is cached on first use instead. Visit two is instant and
 * offline-capable; visit one costs exactly what it costs today.
 */
self.addEventListener("install", () => {
  // Take over as soon as this worker is ready rather than waiting for every
  // tab to close. Safe here because the caches are versioned and the fetch
  // rules are strategy-based, not tied to a manifest of specific files.
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    (async () => {
      const names = await caches.keys();
      await Promise.all(
        names.filter((n) => n !== STATIC_CACHE && n !== PAGES_CACHE).map((n) => caches.delete(n)),
      );
      await self.clients.claim();
    })(),
  );
});

/** Immutable, content-hashed build output. */
function isBuildAsset(url) {
  return url.pathname.startsWith("/_next/static/");
}

/** Our own static files: icons, decoders, the login photograph. */
function isPublicAsset(url) {
  return (
    url.pathname.startsWith("/icons/") ||
    url.pathname.startsWith("/images/") ||
    url.pathname.startsWith("/decoders/") ||
    url.pathname === "/manifest.webmanifest"
  );
}

self.addEventListener("fetch", (event) => {
  const { request } = event;

  // Only GET. A cached POST is meaningless, and intercepting the chat
  // endpoint's streaming POST would break it outright.
  if (request.method !== "GET") return;

  const url = new URL(request.url);

  // Cross-origin is left entirely alone. The API is on another origin in this
  // deployment (NEXT_PUBLIC_API_URL), and the rule below would otherwise have
  // to be trusted to exclude it — a same-origin check is a stronger guarantee
  // than a path match.
  if (url.origin !== self.location.origin) return;

  // NEVER cache telemetry. This is the rule that matters most: a monitoring
  // dashboard serving a cached fleet summary is worse than one showing an
  // error, because a stale reading looks exactly like a fresh one. Anything
  // that could be data goes straight to the network with no fallback.
  if (url.pathname.startsWith("/api/") || url.pathname.startsWith("/_next/data/")) return;

  // CACHE-FIRST for content-hashed build output. The filename changes when the
  // contents change, so a hit can never be stale — this is the one case where
  // cache-first is unconditionally correct, and it is what makes the 3D scene
  // chunk available offline.
  if (isBuildAsset(url)) {
    event.respondWith(cacheFirst(request, STATIC_CACHE));
    return;
  }

  // STALE-WHILE-REVALIDATE for our own static files. Their names are NOT
  // content-hashed (icon-192.png stays icon-192.png), so cache-first would pin
  // a replaced logo forever. This serves the cached copy immediately and
  // refreshes it in the background, so a swap lands on the next load.
  if (isPublicAsset(url)) {
    event.respondWith(staleWhileRevalidate(request, STATIC_CACHE));
    return;
  }

  // NETWORK-FIRST for page navigations, falling back to the last copy of that
  // page. Network-first, not cache-first: an app shell is not versioned, and
  // serving a stale one after a deploy leaves the user on old JavaScript
  // requesting chunks that no longer exist. The cache is the offline
  // fallback, not the primary source.
  if (request.mode === "navigate") {
    event.respondWith(networkFirst(request, PAGES_CACHE));
  }
});

async function cacheFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);
  if (hit) return hit;

  const response = await fetch(request);
  // Only store complete, successful responses. Caching a 206 or an opaque
  // error would serve a broken asset from then on.
  if (response.ok && response.status === 200) cache.put(request, response.clone());
  return response;
}

async function staleWhileRevalidate(request, cacheName) {
  const cache = await caches.open(cacheName);
  const hit = await cache.match(request);

  const network = fetch(request)
    .then((response) => {
      if (response.ok && response.status === 200) cache.put(request, response.clone());
      return response;
    })
    // Offline with nothing cached: let the caller's own error path run.
    .catch(() => hit);

  return hit || network;
}

async function networkFirst(request, cacheName) {
  const cache = await caches.open(cacheName);
  try {
    const response = await fetch(request);
    if (response.ok && response.status === 200) cache.put(request, response.clone());
    return response;
  } catch {
    const hit = await cache.match(request);
    if (hit) return hit;
    // Last resort: the dashboard shell, so an offline deep link still opens
    // the app rather than the browser's dinosaur.
    const shell = await cache.match("/");
    if (shell) return shell;
    throw new Error("offline and nothing cached");
  }
}
